  "hse_advanced.no_audits_desc": "Planifiez des audits de sécurité et des inspections récurrents. Les constats peuvent être convertis en actions CAPA avec des responsables assignés et des échéances.",
  "hse_advanced.no_capa": "Aucune action corrective",
  "hse_advanced.no_capa_desc": "Les Actions Correctives et Préventives (CAPA) permettent de suivre ce qui a été fait pour résoudre un problème et en prévenir la récurrence. Elles sont liées à un incident de sécurité, une JSA, un permis, un audit ou une observation.",
