  "modules.active_modules": "Modules actifs",
  "modules.choose_profile": "Profils d'entreprise",
  "modules.confirm_disable_system": "Désactiver {{name}} ? Cela supprime le module du backend et peut nécessiter un redémarrage de l'application.",
  "modules.confirm_disable_system_title": "Désactiver {{name}} ?",
  "modules.current_profile": "Profil actuel",
  "modules.dev_guide_hint": "Apprenez à créer votre propre module",
  "modules.dev_pack_can_body": "Devise et modèle de taxe par défaut, langues principale et supplémentaires, modules visibles, co-branding, un script d'intégration, et les régions CWICR intégrées et packs de règles de validation à activer.",
  "modules.dev_pack_can_title": "Un pack active ce qui existe déjà",
  "modules.dev_pack_cannot_body": "Il est uniquement déclaratif (Shape A) et n'est jamais exécuté. Il ne peut pas intégrer de nouvelles classes de règles de validation ni ses propres données de Catalogue ; il ne fait que référencer les packs de règles et les régions de coûts déjà fournis par le cœur. Besoin de nouveaux écrans, endpoints, tables ou règles ? Créez plutôt un module.",
  "modules.dev_pack_cannot_title": "Un pack ne contient ni code ni données",
  "modules.dev_pack_contact_us": "Pour référencer votre pack ou être mis en avant, contactez info@neoffice.ch.",
  "modules.dev_pack_intro": "Un pack partenaire est un petit ensemble de préréglages sans code pour un pays, une région ou une entreprise. Il ne contient que des préréglages : identité visuelle (logo et couleurs), locale par défaut, devise et paramètres fiscaux par défaut, modules à afficher ou masquer, un script d'intégration optionnel, et des références aux régions de bases de coûts et aux packs de règles de validation déjà présents dans le cœur. N'importe qui peut en créer un, le partager et laisser un administrateur l'activer en un clic depuis l'onglet Packs partenaires.",
  "modules.dev_pack_open_tab": "Ouvrir l'onglet Packs partenaires",
  "modules.dev_pack_pip_body": "Pour distribuer sur PyPI plutôt que sous forme de dossier/zip, exposez le manifeste via le groupe d'entry-points afin qu'il soit découvert après pip install. Un pack installé via pip peut nécessiter un redémarrage unique du backend.",
  "modules.dev_pack_pip_title": "Optionnel : distribuer en tant que package pip",
  "modules.dev_pack_restart_caveat": "Les packs déposés dans le répertoire de données, et les packs dans le dossier packs/ du dépôt, sont détectés par Rescanner sans redémarrage. Seul un tout nouveau pack livré sous forme de package pip (enregistré via un entry point) peut encore nécessiter un redémarrage du backend avant d'apparaître.",
  "modules.dev_pack_share_contact": "Le pack peut afficher vos coordonnées ou site web à tous ses utilisateurs (votre site partenaire, adresse e-mail de support et votre ligne de co-branding).",
  "modules.dev_pack_share_pip": "Vous pouvez l'ajouter en tant que package à la plateforme (publiez votre package pip), afin que n'importe qui puisse l'installer et l'activer.",
  "modules.dev_pack_share_pr": "Ou contribuez-le directement via une pull request, ce qui le rend visible à tous sans configuration supplémentaire.",
  "modules.dev_pack_share_repo": "Ouvrir le dépôt pour contribuer un pack",
  "modules.dev_pack_share_social": "Nous pouvons également partager des informations sur vous et votre pack via nos réseaux sociaux, afin que davantage de personnes découvrent votre travail.",
  "modules.dev_pack_share_title": "Partager votre pack",
  "modules.dev_pack_step_activate": "L'activer",
  "modules.dev_pack_step_activate_body_v2": "Ouvrez Modules → Packs partenaires, trouvez votre pack et appuyez sur Activer. Il applique la devise, la langue, les normes de validation, la visibilité des modules et l'identité visuelle, et peut installer un projet de démonstration. L'activation est réversible – Désactiver restaure l'état précédent à tout moment.",
  "modules.dev_pack_step_create": "Générer la structure du pack",
  "modules.dev_pack_step_create_body": "Le CLI génère un dossier prêt à modifier avec un manifeste valide, un logo de remplacement, un script d'intégration et un README. Modifiez les espaces réservés et c'est terminé – pas de code à écrire.",
  "modules.dev_pack_step_create_byhand": "Vous préférez le créer manuellement ? Créez simplement un dossier avec un manifest.json. La structure minimale est présentée ci-dessous.",
  "modules.dev_pack_step_install": "L'installer (deux méthodes)",
  "modules.dev_pack_step_install_drop": "Déposez le dossier (ou un .zip de celui-ci) dans le répertoire de données de votre installation sous packs/ – par défaut ~/.openestimate/packs/, à côté de la base de données – puis ouvrez l'onglet Packs partenaires et cliquez sur Rescanner. Aucun redémarrage nécessaire.",
  "modules.dev_pack_step_install_upload": "Ou compressez le dossier en .zip et importez-le directement depuis l'onglet Packs partenaires via le programme d'installation intégré (administrateurs uniquement). Il est extrait dans le même répertoire packs/ et apparaît immédiatement.",
  "modules.dev_pack_step_manifest": "Modifier manifest.json",
  "modules.dev_pack_step_manifest_body": "manifest.json est un PartnerPackManifest sérialisé. slug, partner_name et pack_version identifient le pack ; le reste correspond aux préréglages qu'il applique. Un default_modules vide signifie que tous les modules restent visibles.",
  "modules.dev_pack_title": "Packs partenaires : créez et partagez le vôtre",
  "modules.dev_pack_vs_module": "Un pack ne contient que des préréglages, pas de code. Si vous avez besoin de nouveaux écrans, endpoints ou tables, créez un module (ci-dessous) et référencez-le depuis votre pack via default_modules.",
  "modules.env_pinned_warning": "Un pack partenaire est épinglé via la variable d'environnement OE_PARTNER_PACK. Demandez à votre administrateur de la modifier.",
  "modules.modules_active_label": "modules actifs",
  "modules.modules_label": "modules",
