  "modules.profiles_load_failed": "Échec du chargement des profils",
  "modules.request_card_community_body": "Nous ajoutons votre idée à la feuille de route publique. Si elle rencontre une large demande, nous l'intégrons dans une prochaine version de Neoconstruction – incluse dans chaque installation utilisateur, y compris la vôtre, sans frais.",
  "modules.request_card_community_bullet1": "Gratuit – inclus dans la prochaine version publique si accepté.",
  "modules.request_card_community_bullet2": "Discussion publique GitHub – d'autres équipes peuvent voter, affiner et contribuer.",
  "modules.request_card_community_bullet3": "Idéal pour les normes régionales, intégrations, rapports et outils AI universels.",
  "modules.request_card_community_cta": "Proposer dans notre feuille de route",
  "modules.request_card_community_tag": "Open-source · gratuit pour tous",
  "modules.request_card_community_title": "Pourrait aider d'autres équipes",
  "modules.request_card_private_body": "Pour les flux de travail spécifiques à votre entreprise – nomenclature interne, données de coûts propriétaires, intégrations ERP, sécurité restreinte. Nous concevons, construisons, déployons et maintenons le module de manière privée pour votre équipe.",
  "modules.request_card_private_bullet1": "Devis à périmètre fixe sous 2 jours ouvrables.",
  "modules.request_card_private_bullet2": "Code fermé, déployé uniquement sur votre installation, signé par votre équipe.",
  "modules.request_card_private_bullet3": "Maintenance + SLA inclus – compatible avec chaque version de l'ERP.",
  "modules.request_card_private_cta": "Demander un périmètre et un devis",
  "modules.request_card_private_tag": "Sur mesure · livraison personnalisée",
  "modules.request_card_private_title": "Développé exclusivement pour notre entreprise",
  "modules.request_examples_label": "Exemples de demandes utilisateurs",
  "modules.request_eyebrow": "Un module manquant ?",
  "modules.request_footer_diy": "Vous préférez le créer vous-même ? Chaque module est un petit package Python – le guide développeur vous accompagne de bout en bout en moins d'une heure.",
  "modules.request_footer_diy_cta": "Ouvrir le guide développeur",
  "modules.request_hero_subtitle": "Neoconstruction fonctionne sur une architecture de plug-ins – chaque rapport, intégration, Catalogue régional et outil AI est son propre module. S'il vous manque celui dont vous avez besoin, nous le créerons. Choisissez la voie qui correspond à votre situation.",
  "modules.request_hero_title": "Dites-nous ce dont votre équipe a besoin.",
