  "validation.go_to_element": "Aller à l'élément",
  "validation.intro_body": "La validation est une étape essentielle du pipeline Import → Valider → Enrichir → Estimer. Elle vérifie un Devis (et ses éléments canoniques/BIM liés) par rapport aux ensembles de règles configurés pour le projet — ceux-ci sont dérivés automatiquement de la région et du standard de classification du projet (DIN 276, GAEB, NRM, MasterFormat, boq_quality, …). Chaque constat renvoie à la Position exacte du Devis pour que vous puissiez le corriger à la source.",
  "validation.intro_link_bim": "BIM / modèle canonique",
  "validation.intro_link_boq": "Ouvrir l'éditeur de Devis",
