  "validation.rs_completeness": "Tous les corps d'état couverts, références de coût, détection des lacunes.",
  "validation.rs_din276": "DIN 276 (DACH) structure des groupes de coûts & complétude des Kostengruppe.",
  "validation.rs_gaeb": "Format d'appel d'offres GAEB : structure LV & vérification du format ordinal.",
  "validation.rs_generic": "Règles de validation {{name}}",
  "validation.rs_masterformat": "MasterFormat (US) structure des divisions & format de code.",
  "validation.rs_nrm": "NRM 1/2 (UK) conformité des éléments & règles de mesure.",
  "validation.rule_cost_group_required": "Vérifie que chaque Position dispose d'un Kostengruppe DIN 276 assigné.",
  "validation.rule_no_duplicate_ordinals": "Vérifie que tous les numéros ordinaux dans le Devis sont uniques.",
  "validation.rule_ordinal_format": "Vérifie que les numéros ordinaux respectent le format GAEB LV XX.XX.XXXX.",
  "validation.rule_position_has_description": "Vérifie que chaque Position dispose d'une description significative.",
  "validation.rule_position_has_quantity": "Vérifie que chaque Position du Devis a une quantité supérieure à zéro.",
