  "validation_rules.intro_1": "Toutes les règles de validation intégrées à Neoconstruction. Utilisez ce Catalogue pour voir ce qui est vérifié à chaque import (Devis, modèles CAD, données d'appel d'offres, résultats de prémétré).",
  "validation_rules.intro_2": "Parcourez par sévérité (les erreurs bloquent, les avertissements signalent, les infos suggèrent), par standard (DIN 276 / GAEB / NRM / MasterFormat), ou recherchez par nom.",
  "validation_rules.intro_3": "La sélection des règles par projet est configurée lors du flux d'import — ouvrez un projet, accédez à son onglet Validation et choisissez les ensembles de règles applicables.",
