function applyFrCompletion(lng?: string): void {
  if (lng && lng !== 'fr' && lng !== 'fr-CH') return;
  i18n.addResourceBundle('fr', 'translation', frCompletion, true, true);
}
i18n.on('languageChanged', applyFrCompletion);
applyFrCompletion(i18n.language);

export { frCompletion };
